12	// Largest multiple of ALPHABET.length that fits in a byte (0-255), so rejecting
13	// bytes >= this bound removes the modulo bias that would otherwise favor the
14	// first (256 % 56 = 32) characters of the alphabet.
15	const REJECTION_BOUND = Math.floor(256 / ALPHABET.length) * ALPHABET.length;
