17	export function makeCode(length = 7): string {
18	  let out = '';
19	  while (out.length < length) {
20	    const bytes = new Uint8Array(length - out.length);
21	    crypto.getRandomValues(bytes);
22	    for (const b of bytes) {
23	      if (b >= REJECTION_BOUND) continue;
24	      out += ALPHABET[b % ALPHABET.length];
25	    }
26	  }
27	  return out;
28	}
